def merge_slots(slots: list[list[int]]) -> list[list[int]]:
    if not slots:
        return []
    # Sort intervals by start time
    sorted_slots = sorted(slots, key=lambda interval: interval[0])
    merged = [sorted_slots[0][:]]  # start with a copy of the first interval
    for current in sorted_slots[1:]:
        last = merged[-1]
        # If current interval overlaps or touches the last merged interval
        if current[0] <= last[1]:
            # Extend the end if needed
            if current[1] > last[1]:
                last[1] = current[1]
        else:
            # No overlap, add as a new interval
            merged.append(current[:])
    return merged
```

