def merge_slots(slots: list[list[int]]) -> list[list[int]]:
    if not slots:
        return []
    # Sort intervals by start time
    slots_sorted = sorted(slots, key=lambda interval: interval[0])
    merged = [slots_sorted[0]]
    for current in slots_sorted[1:]:
        prev = merged[-1]
        # If current interval overlaps or touches the previous one, merge them
        if current[0] <= prev[1]:
            prev[1] = max(prev[1], current[1])
        else:
            merged.append(current)
    return merged
