MOD = 1000000007

def stair_ways(n: int, broken: list[int]) -> int:
    broken_set = set(broken)
    ways = [0] * (n + 1)
    ways[0] = 1  # start position is always reachable
    for i in range(1, n + 1):
        if i in broken_set:
            ways[i] = 0
        else:
            total = 0
            if i - 1 >= 0:
                total += ways[i - 1]
            if i - 2 >= 0:
                total += ways[i - 2]
            ways[i] = total % MOD
    return ways[n] % MOD
