def stair_ways(n: int, broken: list[int]) -> int:
    MOD = 1000000007
    broken_set = set(broken)
    dp = [0] * (n + 1)
    dp[0] = 1
    for i in range(1, n + 1):
        if i in broken_set:
            dp[i] = 0
        else:
            ways = dp[i - 1]
            if i >= 2:
                ways += dp[i - 2]
            dp[i] = ways % MOD
    return dp[n]
