from collections import deque

def grid_islands(grid: list[str]) -> list[int]:
    if not grid:
        return []
    rows = len(grid)
    cols = len(grid[0])
    visited = [[False] * cols for _ in range(rows)]
    sizes = []

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == '#' and not visited[r][c]:
                q = deque()
                q.append((r, c))
                visited[r][c] = True
                count = 0
                while q:
                    cr, cc = q.popleft()
                    count += 1
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if grid[nr][nc] == '#' and not visited[nr][nc]:
                                visited[nr][nc] = True
                                q.append((nr, nc))
                sizes.append(count)

    sizes.sort(reverse=True)
    return sizes
```

