def bracket_depth(s: str) -> int:
    opening = {'(', '[', '{'}
    closing = {')', ']', '}'}
    pairs = {'(': ')', '[': ']', '{': '}'}
    stack = []
    max_depth = 0
    for ch in s:
        if ch in opening:
            stack.append(ch)
            current_depth = len(stack)
            if current_depth > max_depth:
                max_depth = current_depth
        elif ch in closing:
            if not stack:
                return -1
            top = stack.pop()
            if pairs[top] != ch:
                return -1
    if stack:
        return -1
    return max_depth
