def bracket_depth(s: str) -> int:
    """
    Returns the maximum nesting depth of correctly matched brackets in the string.
    If the brackets are not properly matched, returns -1.
    Brackets considered are (), [], {}. All other characters are ignored.
    """
    opening = {'(', '[', '{'}
    closing = {')', ']', '}'}
    pairs = {')': '(', ']': '[', '}': '{'}

    stack = []
    max_depth = 0

    for ch in s:
        if ch in opening:
            stack.append(ch)
            max_depth = max(max_depth, len(stack))
        elif ch in closing:
            if not stack or stack[-1] != pairs[ch]:
                return -1
            stack.pop()
    if stack:
        return -1
    return max_depth
```

